For fixed $i,j$, under the condition in Theorem 3, with probability at least $1-exp(-\Omega(\log^2m))$,
\begin{equation}
|\langle h_l(x_i),h_l(x_j) \rangle -K^l_{i,j}|\leq \mathcal{O}(l^{16}\cdot\log^2 m/\sqrt{m})
\end{equation}
And let $Q_l=\sqrt{(1+\frac{1}{L^3}\sum_{k=1}^l||X_{i,k}||^2)\cdot(1+\frac{1}{L^3}\sum_{k=1}^l||X_{j,k}||^2) }$,
\begin{equation}
\begin{aligned}
&K^1_{i,j}= Q_1\cdot \sum_{r=0}^\infty \mu^2_r [(1+\frac{1}{L^3}X_{i,1}^TX_{j,1})/Q_1]^r\\
&K^{l}_{i,j}=Q_l\cdot \sum_{r=0}^\infty \mu^2_r (\{\frac{1}{L^3}X_{i,l}^TX_{j,l}+ K^{l-1}_{i,j}\}/Q_l)^r
\end{aligned}
\end{equation}
In the above equations, $\mu_r=\frac{1}{\sqrt{2\pi}}\int_0^\infty \sqrt{2}xh_r(x)e^{-\frac{x^2}{2}}dx$, $h_r(x)=\frac{1}{\sqrt{r!}}(-1)^re^{\frac{x^2}{2}}\frac{d^r}{dx^r}e^{-\frac{x^2}{2}}.$

Consider equation $h'_l(x_1)=\phi(\bm{W}_lh'_{l-1}(x_l)+\bm{A}_lX_l)$, where the entries of $\bm{W}^l$ and $\bm{A}^l$ are i.i.d. generated from $N(0,\frac{2}{m})$ and $N(0,\frac{2}{L^3m})$.  $\bm{W}^l$, $\bm{A}^l$ and $\bm{W}^{l'}$, $\bm{A}^{l'}$ are independent when $l\neq l'$. With probability at lesat $1-L^2exp(-\Omega(\log^2m))$. For all $1<l\leq L$, we have
\begin{equation}
|h_{l}^T(x)h_{l}(x')-  {h'_{l}}^{T}(x)h'_{l}(x')|\leq \mathcal{O}(L^{2}\log^2m/\sqrt{m})
\end{equation}
for  $x,x'=x_1,x_2$.

Under the condition of Theorem 3, with probability at least $1-\delta$, there exits matrix $\bm{H}^\infty$ satisfying (18) and
\begin{equation}
\sqrt{\widetilde{y}^T (\bm{H}^\infty)^{-1}\widetilde{y}}\leq \mathcal{O}(\mathscr{C}^*).
\end{equation}

For $l\neq l'$, with probability at least $1-exp(-\Omega(\log^2m))$,
\begin{equation}
|\frac{1}{m}\langle \text{Back}_l(x_i)\cdot D_l,\text{Back}_{l'}(x_j)\cdot D_{l'}' \rangle| \leq \mathcal{O}(\frac{L^4\log^4 m}{m^{1/4}}).
\end{equation}
For $l=l'$, there is $F^l_{i,j}$ that, with probability at least $1-exp(-\Omega(\log^2m))$,
\begin{equation}
|\frac{1}{m}\langle \text{Back}_l(x_i)\cdot D_l,\text{Back}_{l}(x_j)\cdot D_{l'}' \rangle- F^l_{i,j}|\leq \mathcal{O}(\frac{L^4\log^4 m}{m^{1/4}}).
\end{equation}
where
\begin{equation}
\Sigma(x)=\frac{1}{2}+\frac{arcsin(x)}{\pi},
\end{equation}
\begin{equation}
F^l_{i,j}\succeq \frac{1}{K}\Sigma( \{\frac{1}{L^3}\langle X_{i,l}, X_{j,l} \rangle +K^{l-1}_{i,j}\}/Q_l).
\end{equation}
and $0<K\leq \mathcal{O}(1/L^4).$

For $l\neq l'$, with probability at least $1-L^2exp(-\Omega(\log^2m))$,
\begin{equation}
|\frac{1}{m}\langle \text{Back}_l(x_i)\cdot D_l,\text{Back}_{l'}(x_j)\cdot D_{l'}' \rangle| \leq \mathcal{O}(\frac{L^4\log^4 m}{m^{1/4}}).
\end{equation}
For $l=l'$, with probability at least $1-L^2exp(-\Omega(\log^2m))$,
\begin{equation}
\frac{1}{m}\langle \text{Back}_l(x_i)\cdot D_l,\text{Back}_{l}(x_j)\cdot D_{l}' \rangle \succeq \Omega(1/L^4)\cdot \Sigma(\{ \frac{1}{L^3}\langle X_{i,l}, X_{j,l} \rangle +K^{l-1}_{i,j}\}/Q_l)\pm \mathcal{O}(\frac{L^4\log^4 m}{m^{1/4}}).
\end{equation}

Under the condition of Theorem 2, let $n$ samples in the training set be $\{x_i,y_i\}_{i=1}^n$. $\widetilde{y}=[F^*(x_1),F^*(x_2),...F^*(x_n)]^T$. Let $\bm{H}$ be a matrix with $H_{i,j}= \frac{1}{m}\langle \nabla_{\widetilde{W}} f(\widetilde{\bm{W}},x_i),\nabla_{\widetilde{W}} f(\widetilde{\bm{W}},x_j) \rangle$. The entries of $\widetilde{\bm{W}}$ are i.i.d. generated from $N(0,\frac{2}{m})$.
If there is a matrix $\bm{H}^\infty \in \mathbb{R}^{n\times n}$ satisfying
\begin{equation}
\bm{H} +\bm{\epsilon}^T\bm{\epsilon} \succeq \bm{H}^\infty \text{ with } ||\bm{\epsilon}||_F\leq 0.01/\mathcal{O}(\mathscr{C}^*),
\end{equation}
and $\sqrt{\widetilde{y}^T (\bm{H}^\infty)^{-1}\widetilde{y}}\leq \mathcal{O}(\mathscr{C}^*)$,
there exits $m^*(n,\delta^{-1},L,\mathscr{C}^*)=poly(n,\delta^{-1},L,\mathscr{C}^*)$ such that, with probability at least $1-\delta$, if $m>m^*$,
\begin{equation}
\frac{1}{n} \sum_{k=1}^n L^{0-1}_{{\cal D}}(\bm{W}^k)\leq \widetilde{\mathcal{O}}[\frac{\widetilde{y}^T (\bm{H}^\infty)^{-1}\widetilde{y}}{n}]+\mathcal{O}(\frac{\log(1/\delta)}{n}).
\end{equation}

Assume there is $\delta\in (0,e^{-1}]$.  Supposing for ${\cal D}=\{x_i,y_i\}$, there is a function $F^*$ belonging to the concept class (9) or (11) such that $y_i\cdot F^*(x_i)\geq 1$ for all $i$.  Let $\bm{W}^k$ be the output of Algorithm a1. There is a parameter $m^*(n,\delta,L,\mathscr{C}^*)=poly(n,\delta^{-1},L,\mathscr{C}^*)$  such that, with probability at least $1-\delta$, if $m>m^*(n,\delta,L)$, there exits parameter $\eta= \mathcal{O}(1/ m)$ that satisfies
\begin{equation}
\frac{1}{n}\sum_{k=1}^nL^{0-1}_{{\cal D}}(\bm{W}^k)\leq \widetilde{\mathcal{O}}[\frac{(\mathscr{C}^*)^2}{n}]+\mathcal{O}(\frac{\log(1/\delta)}{n}).
\end{equation}

Denote $L_i(\bm{W})=\ell(y_i\cdot f(\bm{W},x_i))$. Suppose there exits $\bm{W}^* \in B(\bm{W}_0,R/\sqrt{m})$ with $R\leq poly(n,L)$, $L_i(\bm{W}^*)\leq \frac{1+R^2}{n}$. For any $ \delta$, there exists
\begin{equation}
m^*(n,\delta,R,L)=poly(n,R,L,\delta^{-1})
\end{equation}
such that if $m>m^*$, with probability at least $1-\delta$,  SGD with $\eta=1/m$ for some small enough $\nu$ will output:
\begin{equation}
\frac{1}{n}\sum_{i=1}^n L^{0-1}_{\emph{D}}(\bm{W}^{i})\leq \mathcal{O}(\frac{1}{ n})+ \mathcal{O}(\frac{R^2}{ n})+\mathcal{O}(\frac{\log(1/\delta)}{n}).
\end{equation}

With probability at least $1-\mathcal{O}(n)\cdot exp(-\Omega(\log m))$, for all $i\in [n]$ and $\bm{W},\bm{W}'\in B(\bm{W}_0,\omega)$,
\begin{equation}
|f(\bm{W}',x_i)-f(\bm{W},x_i)-\langle \nabla f(\bm{W},x_i), \bm{W}'-\bm{W}\rangle |\leq \mathcal{O}(\omega^{1/3}L^{10}\log m \sqrt{m})||\bm{W}'-\bm{W}||_2.
\end{equation}

Assume there is $\delta\in [0,e^{-1}]$. Let $n$ samples in ${\cal D}$  be $\{x_i,y_i\}_{i=1}^n$. $\widetilde{y}=[F^*(x_1),F^*(x_2),...F^*(x_n)]^T$. $F^*$ is a function belonging to the concept class (9) or (11) such that $y_i\cdot F^*(x_i)\geq 1$ for all $i$.  There exits matrix $\bm{H}^\infty$ satisfying:
\begin{equation}
\bm{H} +\bm{\epsilon}^T\bm{\epsilon} \succeq \bm{H}^\infty \text{ with } ||\bm{\epsilon}||_F\leq 0.01/ \mathcal{O}(\mathscr{C}^*)
\end{equation}
and
\begin{equation}
\sqrt{ \widetilde{y}^T (\bm{H}^\infty)^{-1}\widetilde{y}}\leq \mathcal{O}(\mathscr{C}^*).
\end{equation}
